import 'package:flutter/material.dart';
import 'package:lottie/lottie.dart';

/// A Lottie animation from a web address: Flux's Lottie(...). An address
/// that isn't https, or that won't load, shows a quiet placeholder.
class StudioLottie extends StatelessWidget {
  const StudioLottie({
    super.key,
    required this.src,
    this.loop = true,
    this.autoplay = true,
    this.fit = BoxFit.contain,
    this.width,
    this.height,
    this.label = '',
  });

  final String src;
  final bool loop;
  final bool autoplay;
  final BoxFit fit;
  final double? width;
  final double? height;
  final String label;

  @override
  Widget build(BuildContext context) {
    final placeholder = SizedBox(
      width: width,
      height: height ?? 160,
      child: Center(child: Icon(Icons.animation, color: Theme.of(context).disabledColor)),
    );
    if (!src.startsWith('https://')) return placeholder;
    final animation = Lottie.network(
      src,
      repeat: loop,
      animate: autoplay,
      fit: fit,
      width: width,
      height: height,
      errorBuilder: (context, error, stackTrace) => placeholder,
    );
    // Decorative unless it was given an alt.
    if (label.isEmpty) return ExcludeSemantics(child: animation);
    return Semantics(label: label, image: true, child: ExcludeSemantics(child: animation));
  }
}
